test.describe('AC3 — the open drawer makes the catalogue unreachable', () => {
  test('@QAIA-US-EVAL-013-004 @AC3 @P1 @decision-table @negative — a tap aimed at the catalogue lands on the drawer and adds nothing',
    async ({ signedIn }) => {
      const { page, inventoryPage, drawer } = signedIn;
      // The card centre is captured BEFORE the drawer opens: once open, the card is covered and
      // its box is what a shopper would still be aiming at.
      const centre = await inventoryPage.firstCardCentre();
      await drawer.open();

      const topmost = await inventoryPage.topmostElementAt(centre.x, centre.y);
      expect(topmost.insideDrawer).toBe(true);

      await page.touchscreen.tap(centre.x, centre.y);
      await expect(inventoryPage.cartBadge).toHaveCount(0);
    });

  test('@QAIA-US-EVAL-013-005 @AC3 @P2 @decision-table — control cell: with the drawer closed the same viewport does add to the cart',
    async ({ signedIn }) => {
      const { inventoryPage, drawer } = signedIn;
      await drawer.open();
      await drawer.close();
      await inventoryPage.firstAddToCart.tap();
      await expect(inventoryPage.cartBadge).toHaveText('1');
    });
});

test.describe('AC4 — drawer state transitions and sole-route-to-logout', () => {
  test('@QAIA-US-EVAL-013-006 @AC4 @P1 @state-transition — tapping the burger opens the drawer',
    async ({ signedIn }) => {
      const { drawer } = signedIn;
      expect(await drawer.ariaHidden()).toBe('true');
      await drawer.burger.tap();
      await expect(drawer.wrapper).toHaveAttribute('aria-hidden', 'false');
    });

  test('@QAIA-US-EVAL-013-007 @AC4 @P1 @state-transition — tapping the close control closes the drawer',
    async ({ signedIn }) => {
      const { drawer } = signedIn;
      await drawer.open();
      await drawer.closeButton.tap();
      await expect(drawer.wrapper).toHaveAttribute('aria-hidden', 'true');
    });

  test('@QAIA-US-EVAL-013-008 @AC4 @P1 @state-transition — the drawer still opens after two full open/close cycles',
    async ({ signedIn }) => {
      const { drawer } = signedIn;
      await drawer.open(); await drawer.close();
      await drawer.open(); await drawer.close();
      await drawer.burger.tap();
      await expect(drawer.wrapper).toHaveAttribute('aria-hidden', 'false');
    });

  test('@QAIA-US-EVAL-013-009 @AC4 @P2 @error-guessing — exactly one sign-out control exists on a phone, and it is inside the drawer',
    async ({ signedIn }) => {
      const { drawer } = signedIn;
      await drawer.open();
      const controls = await drawer.signOutControlsOnPage();
      expect(controls).toHaveLength(1);
      expect(controls[0].insideDrawer).toBe(true);
    });
});

test.describe('AC7 — touch-target size against the published WCAG 2.2 SC 2.5.8 oracle', () => {
  test('@QAIA-US-EVAL-013-016 @AC7 @P1 @boundary @oracle:wcag-2.2-2.5.8 — the burger is 20x20 CSS px, below the 24x24 minimum',
    async ({ signedIn }) => {
      const { drawer } = signedIn;
      const size = await drawer.burgerSize();
      // Two distinct assertions: the measured value (the SUT fact), and the oracle comparison
      // (the requirement). The scenario asserts a KNOWN-FAILING accessibility property of the
      // target — it passes when the target still measures 20x20, which is the finding.
      expect(size).toEqual({ width: 20, height: 20 });
      expect(size.width).toBeLessThan(24);
      expect(size.height).toBeLessThan(24);
    });
});
